      const invalidItem = reportItems.find(item => item.date && (item.date < periodStart || item.date > periodEnd));
      if (invalidItem) {
          alert(`ERRO DE DATA: O gasto "${invalidItem.description || 'sem descrição'}" possui data fora do período.`);
          return false;
      }
      return true;
  };

