      </div>
    );
  };

  return (
    <>
        {renderContent()}
        {isConfirmEfetivarHistoricoModal && (
            <Modal title="Confirmar efetivação" onClose={() => setIsConfirmEfetivarHistoricoModal(false)}>
                <div className="text-center p-4 space-y-4">
